        $articles = [
            ['category' => 'care', 'slug' => 'new-canary-care-basics', 'title' => 'أساسيات العناية بكناري جديد', 'summary' => 'خطوات هادئة لاستقبال الكناري ومراقبة تأقلمه وترتيب القفص والروتين اليومي.', 'image' => '/images/birds/yellow-canary.jpg', 'tags' => ['العناية', 'المبتدئ', 'القفص'], 'content' => "ضع القفص في مكان هادئ وثابت بعيدًا عن تيار الهواء المباشر وروائح المطبخ والدخان. يحتاج الطائر الجديد إلى وقت ليتعرف إلى المكان، لذلك تجنب كثرة الإمساك به أو تغيير موضع القفص في الأيام الأولى.\n\nوفّر ماءً نظيفًا يوميًا وغذاءً مناسبًا للكناري، وراقب الأكل والشرب وحركة الطائر وشكل الفضلات من دون إزعاجه. لا تغيّر النظام الغذائي فجأة؛ أدخل أي طعام جديد تدريجيًا.\n\nنظّف أوعية الماء والطعام باستمرار، ونظف أرضية القفص دوريًا. امنح الطائر دورة ضوء وهدوء منتظمة للنوم، ولا تترك الإضاءة حتى ساعات متأخرة.\n\nإذا لاحظت خمولًا واضحًا، أو جلوسًا مستمرًا في أرضية القفص، أو صعوبة في التنفس، فاعزل الطائر عن بقية الطيور وتواصل مع طبيب بيطري مختص بالطيور."],
            ['category' => 'care', 'slug' => 'best-canary-diet', 'title' => 'أفضل نظام غذائي للكناري', 'summary' => 'كيف تبني غذاءً متوازنًا وتتفادى التغيير المفاجئ والإفراط في الأطعمة الدسمة.', 'image' => '/images/birds/classic-canary.jpg', 'tags' => ['التغذية', 'العناية', 'الصحة'], 'content' => "ابدأ بخليط بذور أو غذاء متكامل مخصص للكناري من مصدر موثوق، وقدمه بكمية مناسبة بدل ملء المعلفة بلا حساب. راقب ما يأكله الطائر فعلًا، لأن قشور البذور قد تجعل الوعاء يبدو ممتلئًا.\n\nيمكن تقديم كميات صغيرة من الخضار الآمنة والمغسولة جيدًا، مع إزالة البقايا بعد مدة قصيرة حتى لا تفسد. لا تجعل المكافآت والأطعمة الدسمة جزءًا كبيرًا من الوجبة اليومية.\n\nالماء النظيف أساس يومي، ويجب غسل الوعاء قبل إعادة تعبئته. لا تضف مكملات أو فيتامينات عشوائيًا، خصوصًا إذا كان الطائر يتناول غذاءً متوازنًا؛ فالزيادة قد تكون ضارة مثل النقص.\n\nاحتياجات الطائر تختلف في القلش والتفريخ والنمو، لذلك راقب الوزن والنشاط واستشر طبيبًا بيطريًا عند الحاجة إلى برنامج علاجي أو مكمل محدد."],
            ['category' => 'care', 'slug' => 'canary-molting-signs', 'title' => 'كيف تعرف أن الكناري دخل في القلش؟', 'summary' => 'العلامات المعتادة لتبديل الريش والفرق بينها وبين تساقط الريش غير الطبيعي.', 'image' => '/images/birds/yellow-canary.jpg', 'tags' => ['القلش', 'الريش', 'العناية'], 'content' => "القلش مرحلة طبيعية يستبدل فيها الكناري ريشه القديم. قد تلاحظ ريشًا متناثرًا حول القفص، وظهور ريش جديد على هيئة أنابيب صغيرة، مع انخفاض النشاط أو التغريد مؤقتًا.\n\nخلال هذه الفترة يحتاج الطائر إلى الهدوء والنوم المنتظم والغذاء المتوازن. تجنب إجهاده بالنقل المتكرر أو التدريب المكثف، وحافظ على نظافة القفص لأن كمية الريش المتساقط تزداد.\n\nالقلش الطبيعي يكون تدريجيًا ولا يترك عادة مساحات كبيرة عارية أو جروحًا. أما التساقط الموضعي الشديد، أو الحك المستمر، أو الاحمرار، أو تدهور الحالة العامة فقد يدل على مشكلة أخرى ويحتاج إلى تقييم بيطري.\n\nدوّن بداية التغير ومدته، فمتابعة النمط السنوي تساعدك على معرفة ما هو معتاد لطائرك."],
            ['category' => 'common-problems', 'slug' => 'singing-after-molt', 'title' => 'متى يعود الذكر للتغريد بعد القلش؟', 'summary' => 'لماذا يخف التغريد أثناء القلش وما العوامل التي تساعد الذكر على العودة تدريجيًا.', 'image' => '/images/birds/yellow-canary.jpg', 'tags' => ['التغريد', 'القلش', 'الذكر'], 'content' => "يخف تغريد كثير من الذكور أثناء القلش لأن الجسم يوجّه طاقته إلى تكوين الريش الجديد. العودة لا تحدث في يوم واحد؛ تبدأ غالبًا بأصوات قصيرة ثم يزداد انتظام التغريد مع اكتمال الريش وتحسن النشاط.\n\nوفّر نومًا منتظمًا وغذاءً متوازنًا ومكانًا هادئًا، ولا تحاول تحفيز الطائر بإضاءة طويلة أو تغييرات مفاجئة. يختلف التوقيت بين طائر وآخر بحسب العمر والصحة وطبيعة القلش والموسم.\n\nإذا اكتمل الريش وبقي الطائر خاملًا أو ظهرت معه أعراض أخرى مثل تغير التنفس أو الشهية أو الفضلات، فلا تعتبر الصمت مشكلة سلوكية فقط، واستشر طبيبًا بيطريًا مختصًا بالطيور."],
            ['category' => 'readiness', 'slug' => 'male-canary-readiness-signs', 'title' => 'علامات جهوزية ذكر الكناري', 'summary' => 'دلائل سلوكية وموسمية تساعد على تقييم جهوزية الذكر من دون الاعتماد على التغريد وحده.', 'image' => '/images/birds/yellow-canary.jpg', 'tags' => ['الجهوزية', 'الذكر', 'التزاوج'], 'content' => "يُعد التغريد القوي والمتكرر من العلامات المعروفة، لكنه ليس العلامة الوحيدة. راقب النشاط العام واستجابة الذكر للأنثى ووضعية الجسم، وتأكد أولًا من اكتمال القلش واستقرار الصحة.\n\nالجهوزية مرتبطة بالموسم ودورة الضوء والعمر والحالة الغذائية. لا ترفع ساعات الإضاءة بسرعة ولا تجمع الزوج مباشرة لمجرد سماع التغريد؛ التعارف التدريجي يقلل التوتر والمشاجرات.\n\nقد يغرد ذكر غير جاهز تمامًا، وقد يتأخر ذكر سليم بسبب تغير المكان أو القلش أو الضغط. اجمع عدة علامات معًا، وراقب السلوك لعدة أيام قبل تجهيز الزوج."],
            ['category' => 'readiness', 'slug' => 'female-canary-readiness-signs', 'title' => 'علامات جهوزية أنثى الكناري', 'summary' => 'سلوك جمع مواد العش والاستجابة للذكر والعلامات التي تسبق وضع البيض.', 'image' => '/images/birds/classic-canary.jpg', 'tags' => ['الجهوزية', 'الأنثى', 'العش'], 'content' => "قد تبدأ الأنثى الجاهزة بالبحث عن مكان للعش وحمل الخيوط أو مواد التعشيش، وتزداد استجابتها لتغريد الذكر. هذه العلامات تصبح أوضح عند توافر الموسم المناسب والصحة الجيدة.\n\nقد تعبث أنثى غير جاهزة بمواد العش ثم تتركها، لذلك لا تعتمد على تصرف واحد. راقب اكتمال بناء العش، ووضعية التلقيح، والهدوء عند وجود الذكر خلف حاجز التعارف.\n\nلا تدفع الأنثى إلى التفريخ إن كانت صغيرة أو ضعيفة أو في القلش. تأكد من الغذاء المتوازن ومصدر الكالسيوم المناسب بإرشاد مختص، واطلب مساعدة بيطرية عند الإجهاد أو صعوبة وضع البيض."],
            ['category' => 'sexing', 'slug' => 'male-female-canary-difference', 'title' => 'كيفية التفريق بين الذكر والأنثى', 'summary' => 'ما الذي يمكن أن يخبرك به التغريد والسلوك والفحص، ولماذا لا تكفي علامة واحدة دائمًا.', 'image' => '/images/birds/gloster-canary.jpg', 'tags' => ['تحديد الجنس', 'الذكر', 'الأنثى'], 'content' => "التغريد الطويل المركب يرجح أن الطائر ذكر، بينما تصدر الإناث غالبًا أصواتًا أقصر، لكن هذا ليس حكمًا مطلقًا؛ فقد تتأخر بعض الذكور في التغريد وقد تغرد بعض الإناث بدرجات مختلفة.\n\nفي موسم التزاوج تصبح الفروق السلوكية والجسدية أوضح لدى المربي الخبير. خارج الموسم أو عند الطيور الصغيرة قد يكون التحديد أصعب، ولا يكفي شكل الرأس أو اللون وحده في معظم الحالات.\n\nإذا كان تحديد الجنس مهمًا لبرنامج تزاوج أو شراء، اطلب فحصًا من مربي موثوق أو طبيب مختص، وقد يكون الفحص الجيني خيارًا أدق عندما تتشابه العلامات."],
            ['category' => 'readiness', 'slug' => 'prepare-canaries-for-breeding-season', 'title' => 'تجهيز الكناري لموسم التزاوج', 'summary' => 'خطة تدريجية تبدأ بالصحة والضوء والغذاء وتنتهي بالتعارف الآمن بين الزوج.', 'image' => '/images/birds/gloster-canary.jpg', 'tags' => ['التزاوج', 'الجهوزية', 'التجهيز'], 'content' => "ابدأ بتقييم صحة كل طائر قبل الجمع، وتأكد من انتهاء القلش وعدم وجود أعراض مرضية. نظّف الأقفاص والأدوات وجهز قفص التفريخ والعش ومواد تعشيش آمنة.\n\nاجعل تغييرات الضوء والغذاء تدريجية. لا تستخدم المكملات كبديل عن التغذية المتوازنة، ولا ترفع الجرعات دون حاجة واضحة أو توجيه مختص.\n\nضع الذكر والأنثى بحيث يسمعان ويريان بعضهما خلف حاجز في البداية. راقب الهدوء والاستجابة وبناء العش، ثم اسمح بالتقارب عندما تظهر علامات الجهوزية على الطرفين.\n\nاحتفظ بخطة للفصل إذا ظهرت مطاردة عنيفة أو إصابة، وتجنب تكرار التفريخ بما يرهق الأنثى."],
            ['category' => 'breeding', 'slug' => 'canary-eggs-and-chicks-care', 'title' => 'العناية بالبيض والفراخ', 'summary' => 'كيف توفر الهدوء والنظافة والغذاء وتراقب الأسرة من دون تدخل زائد.', 'image' => '/images/birds/classic-canary.jpg', 'tags' => ['البيض', 'الفراخ', 'التفريخ'], 'content' => "ثبّت القفص في مكان هادئ وتجنب فحص العش مرات كثيرة. راقب من بعيد ما إذا كانت الأنثى تحضن والزوج يطعم، وسجل مواعيد وضع البيض والفقس بدل الاعتماد على الذاكرة.\n\nوفّر غذاءً مناسبًا لمرحلة التفريخ وماءً نظيفًا يوميًا، وأزل الطعام الرطب قبل فساده. حافظ على نظافة محيط العش من دون تفكيكه أو إزعاج الفراخ بلا ضرورة.\n\nتأكد من أن الفراخ دافئة وأن الحوصلة تمتلئ بالطعام وأن النمو متقارب. الفرخ البارد أو الخامل أو الذي لا يُطعم يحتاج إلى تدخل سريع من شخص خبير أو طبيب بيطري.\n\nلا تفصل الفراخ لمجرد خروجها من العش؛ انتظر حتى تعتمد على نفسها في الأكل، وراقب الأب إذا استمر في الإطعام خلال مرحلة الفطام."],
            ['category' => 'health', 'slug' => 'canary-warning-symptoms', 'title' => 'أشهر الأمراض والأعراض التي تستدعي الانتباه', 'summary' => 'علامات إنذار عامة تساعدك على التحرك مبكرًا من دون محاولة تشخيص المرض في المنزل.', 'image' => '/images/birds/classic-canary.jpg', 'tags' => ['الصحة', 'الأعراض', 'البيطري'], 'content' => "الطيور قد تخفي المرض، لذلك يستحق التغير المفاجئ الانتباه: خمول واضح، نفش مستمر، قلة أكل، تغير ملحوظ في الفضلات، فقدان وزن، أو الجلوس في أرضية القفص.\n\nصعوبة التنفس، فتح المنقار للتنفس، حركة الذيل مع كل نفس، النزف، التشنج، أو العجز عن الوقوف علامات تستدعي تواصلًا بيطريًا عاجلًا.\n\nاعزل الطائر المريض عن بقية الطيور، ووفّر له الدفء والهدوء والماء، ونظف يديك والأدوات بين الأقفاص. لا تعطِ مضادًا حيويًا أو دواءً بشريًا بناءً على التخمين، لأن الأعراض المتشابهة قد تكون لها أسباب مختلفة.\n\nهذا الدليل للتوعية وليس تشخيصًا. الطبيب البيطري المختص بالطيور هو الأقدر على الفحص واختيار العلاج والجرعة المناسبة."],
            ['category' => 'health', 'slug' => 'canary-mites-prevention', 'title' => 'الفاش وكيفية الوقاية منه', 'summary' => 'خطوات نظافة ومراقبة تقلل خطر الطفيليات وتوضح متى تحتاج إلى علاج مختص.', 'image' => '/images/birds/gloster-canary.jpg', 'tags' => ['الفاش', 'الوقاية', 'النظافة'], 'content' => "قد تسبب الطفيليات حكة وقلقًا أثناء الليل وتلفًا في الريش، لكن هذه العلامات ليست خاصة بالفاش وحده. افحص المجاثم والزوايا ونظافة القفص، وراقب الطائر في أوقات مختلفة.\n\nللوقاية، اعزل أي طائر جديد فترة مناسبة، ولا تتبادل الأقفاص والأعشاش والأدوات بين الطيور قبل تنظيفها. نظف الشقوق والمجاثم وبدّل المواد المتسخة بانتظام.\n\nإذا اشتبهت بإصابة، لا ترش مبيدًا منزليًا قرب الطائر ولا تستخدم جرعات عشوائية من علاجات قوية. بعض المنتجات سامة للطيور، والعلاج الصحيح يعتمد على نوع الطفيل ووزن الطائر وحالته. استشر طبيبًا بيطريًا لتأكيد السبب ووضع خطة آمنة للطيور والبيئة معًا."],
            ['category' => 'breeds', 'slug' => 'popular-canary-breeds', 'title' => 'أشهر سلالات الكناري وكيف تختلف عن بعضها', 'summary' => 'مدخل إلى سلالات الغناء والشكل واللون وما الذي ينبغي مقارنته قبل الاختيار.', 'image' => '/images/birds/gloster-canary.jpg', 'tags' => ['السلالات', 'يوركشاير', 'جلوستر'], 'content' => "تُربى سلالات الكناري لأهداف مختلفة؛ بعضها مشهور بالغناء، وبعضها بالشكل ووضعية الجسم أو بنية الريش، وبعضها بالألوان. لذلك ابدأ بتحديد ما يهمك قبل المقارنة.\n\nاليوركشاير معروف بقامته وشكله الطويل، بينما يتميز الجلوستر بحجمه الأصغر ووجود التاج في بعض أنواعه. وتوجد سلالات شكل أخرى مثل المونشنر واللانكشير، إلى جانب سلالات غناء وألوان متعددة.\n\nاسم السلالة وحده لا يضمن جودة الطائر. افحص الصحة والنشاط والريش والعمر والسجل المتاح، وشاهد صورًا وفيديو واضحًا واسأل عن طريقة التربية والغذاء.\n\nللمبتدئ، قد يكون الطائر السليم المعتاد على بيئته المحلية خيارًا أفضل من سلالة تحتاج إلى عناية متخصصة لمجرد أن اسمها أشهر."],
        ];

        foreach ($articles as $index => $data) {
            $article = Article::firstOrCreate(
                ['slug' => $data['slug']],
                [
                    'category_id' => $categories[$data['category']]->id,
                    'title' => $data['title'],
                    'summary' => $data['summary'],
                    'content' => $data['content'],
                    'featured_image' => $data['image'],
                    'status' => 'published',
                    'published_at' => now()->subDays(count($articles) - $index),
                ]
            );

            $tagIds = collect($data['tags'])->map(function ($name) {
                return Tag::firstOrCreate(
                    ['name' => $name],
                    ['slug' => 'tag-'.substr(sha1($name), 0, 10)]
                )->id;
            });
            $article->tags()->syncWithoutDetaching($tagIds);
        }
    }
}
